package branding

import (
	_ "embed"
	"strings"
)

// ThirdPartyLicenses holds the licence notices of the Go standard library
// and of every third-party module compiled into dbcc: a summary table, then
// each full text (spec 7.1, A16). It is generated by `make licenses`
// (gen/licenses); do not edit it by hand.
//
//go:embed THIRD_PARTY_LICENSES.txt
var ThirdPartyLicenses string

// License is one row of the summary table of ThirdPartyLicenses.
type License struct {
	Module  string // module path; "std" is the Go standard library
	Version string
	Licence string // SPDX identifier, e.g. MIT, Apache-2.0, MPL-2.0
}

// Licenses is the parsed summary table of ThirdPartyLicenses.
var Licenses = ParseLicenses(ThirdPartyLicenses)

// ParseLicenses reads the summary table of a THIRD_PARTY_LICENSES.txt: the
// rows after the "Module Version Licence" header up to the first blank line.
func ParseLicenses(text string) []License {
	var out []License
	in := false
	for _, l := range strings.Split(text, "\n") {
		f := strings.Fields(l)
		if !in {
			in = len(f) == 3 && f[0] == "Module" && f[1] == "Version" && f[2] == "Licence"
			continue
		}
		if len(f) == 0 {
			break
		}
		if len(f) == 3 {
			out = append(out, License{Module: f[0], Version: f[1], Licence: f[2]})
		}
	}
	return out
}
